{
 "rules": [
  {
   "rule_id": "KBYY-S2-R07-01",
   "status": "OK",
   "label": "저금통 금리 우대",
   "source": {
    "quote": "▪ 연 1.9% (최대 100만원까지)"
   },
   "condition": {
    "and": [
     {
      "exists": {
       "event": "DEPOSIT",
       "within": {
        "ref": "$low_saving_account_window"
       },
       "where": {
        "min_amount": 1000000
       }
      }
     },
     {
      "var": "account.reserved_amount"
     },
     {
      "op": "!=",
      "values": [
       0
      ]
     }
    ]
   },
   "let": {
    "low_saving_account_window": {
     "month_range": {
      "from": {
       "anchor": "contract.start_date",
       "offset_months": 0,
       "day": "first"
      },
      "to": {
       "anchor": "contract.maturity_date",
       "offset_months": -1,
       "day": "last"
      }
     }
    }
   },
   "effect": {
    "type": "RATE_ADD",
    "value": 1.9,
    "unit": "%p",
    "applies_to": "BASE_RATE"
   }
  },
  {
   "rule_id": "KBYY-S2-R07-02",
   "status": "OK",
   "label": "저금통 금액 한도",
   "source": {
    "quote": "적용한도 : 저금통 금액 설정은 최대 100만원(1만원 단위)까지 가능"
   },
   "condition": {
    "and": [
     {
      "var": "account.reserved_amount"
     },
     {
      "op": ">=",
      "values": [
       1000000
      ]
     }
    ]
   },
   "effect": {
    "type": "LIMIT_AMOUNT",
    "value": 1000000
   }
  }
 ]
}

