raw_first:
{
 "rules": [
  {
   "rule_id": "R-KBYY-S2-R08-01",
   "status": "OK",
   "label": "이자 지급시기",
   "source": {
    "quote": "매년 2월, 5월, 8월, 11월의 둘째 금요일에 결산하여 다음날 원금에 더함"
   },
   "condition": {
    "and": [
     {
      "in": [
       {
        "var": "contract.termination_type"
       },
       ["MATURITY", "EARLY", "PARTIAL", "MID_TERM"]
      ]
     },
     {
      "not": {
        "in": [
         {
          "var": "contract.termination_type"
         },
         ["NONE"]
        ]
      }
     }
    ]
   },
   "effect": {
    "type": "SERVICE_PROVIDE",
    "target": "INTEREST_PAYMENT",
    "value": 1,
    "unit": "YEAR"
   }
  },
  {
   "rule_id": "R-KBYY-S2-R08-02",
   "status": "OK",
   "label": "이자 계산 방식 변경",
   "source": {
    "quote": "최종거래일로부터 5년이 경과한 날부터는 이자에 원금을 더하지 않고, 계좌해지 또는 추가 입출금 거래 발생일에 일괄 계산하여 지급할 수 있습니다"
   },
   "condition": {
    "and": [
     {
      ">=": [
       {
        "var": "account.last_transaction_date"
       },
       "5 years ago"
      ]
     },
     {
      "in": [
       {
        "var": "contract.termination_type"
       },
       ["MATURITY", "EARLY", "PARTIAL", "MID_TERM"]
      ]
     }
    ]
   },
   "effect": {
    "type": "SERVICE_PROVIDE",
    "target": "INTEREST_CALCULATION",
    "value": "BATCH",
    "unit": "DAY"
   }
  }
 ]
}

