       "anchor": "contract.reference_date",
       "offset_months": -1,
       "day": "last"
      }
     }
    }
   },
   "condition": {
    "exists": {
     "event": "CARD_USAGE",
     "within": {
      "ref": "$window"
     }
    }
   },
   "effect": {
    "type": "FEE_WAIVE",
    "target": "EBANK_TRANSFER",
    "value": "UNLIMITED"
   }
  },
  {
   "rule_id": "R-KBYY-S2-R12-02",
   "status": "OK",
   "label": "자동화기기 시간외출금수수료 면제",
   "source": {
    "quote": "KB국민은행 자동화기기 시간외출금수수료 |"
   },
   "let": {
    "window": {
     "month_range": {
      "from": {
       "anchor": "contract.reference_date",
       "offset_months": -1,
       "day": "first"
      },
      "to": {
       "anchor": "contract.reference_date",
       "offset_months": -1,
       "day": "last"
      }
     }
    }
   },
   "condition": {
    "exists": {
     "event": "CARD_USAGE",
     "within": {
      "ref": "$window"
     }
    }
   },
   "effect": {
    "type": "FEE_WAIVE",
    "target": "ATM_WITHDRAW_AFTER_HOURS",
    "value": "UNLIMITED"
   }
  },
  {
   "rule_id": "R-KBYY-S2-R12-03",
   "status": "OK",
   "label": "면제기간 적용",
   "source": {
    "quote": "면제기간: 이번 달 11일부터 다음 달 10일까지"
   },
   "condition": {
    "and": [
     {
      ">=": [
       {
        "var": "contract.reference_date"
       },
       "2023-11-11"
      ]
     },
     {
      "<": [
       {
        "var": "contract.reference_date"
       },
       "2023-12-11"
      ]
     }
    ]
   },
   "effect": {
    "type": "FEE_WAIVE",
    "target": "EBANK_TRANSFER",
    "value": "UNLIMITED"
   }
  },
  {
   "rule_id": "R-KBYY-S2-R12-04",
   "status": "OK",
   "label": "신규/전환 고객 면제",
   "source": {
    "quote": "※ 이 통장의 신규(전환)일로부터 다음 다음 달 10일까지는 은행 거래실적에 관계없이 면제"
   },
   "condition": {
    "and": [
     {
      ">=": [
       {
        "var": "contract.reference_date"
       },
       {
        "date": {
         "anchor": "contract.switch_date",
         "offset_months": 2,
         "day": "10"
        }
       }
      ]
     },
     {
      "<": [
       {
        "var": "contract.reference_date"
       },
       {
        "date": {
         "anchor": "contract.switch_date",
         "offset_months": 3,
         "day": "10"
        }
       }
      ]
     }
    ]
   },
   "effect": {
    "type": "FEE_WAIVE",
    "target": "EBANK_TRANSFER",
    "value": "UNLIMITED"
   }
  }
 ]
}

