raw_first:
{
 "rules": [
  {
   "rule_id": "R-KBYY-S3-R05-01",
   "status": "OK",
   "label": "사전통지 방법",
   "source": {
    "quote": "서면, 우편, 전자우편, 전화, 팩스, 휴대전화 문자메시지 또는 이에 준하는 전자적 의사표시 중 2개 이상의 방법으로 축소·변경 6개월 전부터 매월 고지"
   },
   "condition": {
    "and": [
     {
      ">=": [
       {
        "var": "contract.notice_months"
       },
       6
      ]
     },
     {
      ">=": [
       {
        "count_distinct_months": {
         "event": "NOTICE_METHOD",
         "within": {
          "ref": "$notice_window"
         }
        }
       },
       2
      ]
     }
    ]
   },
   "let": {
    "notice_window": {
     "month_range": {
      "from": {
       "anchor": "contract.start_date",
       "offset_months": 6,
       "day": "first"
      },
      "to": {
       "anchor": "contract.end_date",
       "offset_months": -1,
       "day": "last"
      }
     }
    }
   },
   "effect": {
    "type": "REQUIRE",
    "value": "NOTICE"
   }
  },
  {
   "rule_id": "R-KBYY-S3-R05-02",
   "status": "OK",
   "label": "불가피한 사유",
   "source": {
    "quote": "단, 금융회사의 휴업·파산·경영상의 위기 또는 연계․제휴서비스등을 제공하는 자의 일방적인 제공 중단 등 6개월 전부터 고지하기 어려운 불가피한 경우에는 해당 상황이 발생하는 즉시 고지"
   },
   "guard": {
    "in": [
     {
      "var": "contract.notice_exception"
     },
     [
      "BANK_CLOSURE",
      "BANKRUPTCY",
      "FINANCIAL_Crisis",
      "PARTNER_SERVICE_TERMINATION"
     ]
    ]
   },
   "condition": {
    "exists": {
     "event": "NOTICE"
    }
   },
   "effect": {
    "type": "REQUIRE",
    "value": "NOTICE"
   }
  }
 ]
}

