{
 "rules": [
  {
   "rule_id": "KBONE-S2-R17-01",
   "status": "OK",
   "label": "휴면예금 출연 조건",
   "source": {
    "quote": "예금 만기일 또는 이자지급을 포함한 최종거래일 이후 5년 이내 계좌를 해지하지 않을 경우 예금거래기본약관 제9조의2 휴면예금 및 출연에 따라 휴면예금은 \"서민금융진흥원(국번없이 1397)\"에 출연주)될 수 있으며, 이 경우 서민금융진흥원을 통해 휴면예금을 찾으실 수 있습니다."
   },
   "condition": {
    "and": [
     {
      "not": {
       "exists": {
        "event": "TERMINATION",
        "within": {
         "month_range": {
          "from": {
           "anchor": "account.last_transaction_date",
           "offset_months": 0,
           "day": "first"
          },
          "to": {
           "anchor": "account.last_transaction_date",
           "offset_months": 60,
           "day": "last"
          }
         }
        }
       }
      }
     },
     {
      "and": [
       {
        "var": "contract.termination_type"
       },
       {
        "in": [
         "MATURITY",
         "EARLY",
         "PARTIAL",
         "MID_TERM",
         "NONE"
        ]
       }
      ]
     }
    ]
   },
   "effect": {
    "type": "DISQUALIFY"
   }
  }
 ]
}

